    color:black;

}

@media print {
    /* Set page size and margins for printing */
    @page {
        size: 80mm 297mm;
        margin: 5mm; /* Adjust margin to create white space at edges */
        box-sizing: border-box; /* Ensure margins are included in the total size */
    }

    /* Ensure the print format size is 80mm x 297mm */
    .print-format {
        width: 100%; /* Use full width of the available area minus margins */
        height: auto; /* Allow height to adjust if content overflows */
        max-height: 297mm; /* Prevent exceeding page height */
        overflow: auto; /* Allow scrolling if content is too large */
        box-sizing: border-box; /* Include padding in width/height calculations */
        padding: 0; /* Remove any extra padding */
    }

    /* Ensure content doesn't get cut off */
    .item-table, .totals-table {
        page-break-inside: avoid; /* Prevent breaking the tables inside */
        width: 100%; /* Use full width for the tables */
        direction: rtl; /* Ensure right-to-left text flow */
    }

    /* Adjust styles for Arabic language */
    html[lang="العربية"] .item-table {
        width: 100%; /* Ensure the item table uses full width */
        margin-left: 0; /* Reset any left margin */
        margin-right: auto; /* Center align */
    }

    /* Styling for Arabic text */
    html[lang="ar"] .print-format {
        direction: rtl; /* Right-to-left direction */
        text-align: right; /* Right-align text */
    }
}
